if (EMOJIS.length !== 1424) throw new Error(`Check emoji count, now: ${EMOJIS.length}`);
let sharedAudioCtx = null;
document.addEventListener('click', function warmupAudioOnce() {
  try {
    if (!sharedAudioCtx) sharedAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (sharedAudioCtx.state === 'suspended') sharedAudioCtx.resume();
  } catch (e) {}
  document.removeEventListener('click', warmupAudioOnce);
}, { once: true });
function playPingSound() {
  try {
    if (!sharedAudioCtx) sharedAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const ctx = sharedAudioCtx;
    if (ctx.state === 'suspended') ctx.resume();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.type = 'sine';
    osc.frequency.setValueAtTime(880, ctx.currentTime);
    osc.frequency.exponentialRampToValueAtTime(1200, ctx.currentTime + 0.1);
    gain.gain.setValueAtTime(0.3, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + 0.3);
  } catch (e) {}
}
function showPrettyMessageBox(userName, onSend) {
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:99999;display:flex;align-items:center;justify-content:center;';
  const box = document.createElement('div');
  box.style.cssText = 'background:linear-gradient(180deg,#2c2c3e,#1a1a28);border-radius:20px;padding:20px;width:280px;box-shadow:0 10px 40px rgba(0,0,0,0.5);border:1px solid rgba(255,255,255,0.1);';
  const title = document.createElement('div');
  title.textContent = userName + ' ile mesajlasma';
  title.style.cssText = 'color:#fff;font-weight:bold;font-size:16px;margin-bottom:12px;text-align:center;';
  const input = document.createElement('textarea');
  input.placeholder = 'Mesajinizi yazin...';
  input.style.cssText = 'width:100%;box-sizing:border-box;background:#0f0f18;color:#fff;border:1px solid rgba(255,255,255,0.15);border-radius:16px;padding:12px 14px;font-size:14px;resize:none;height:70px;outline:none;';
  const btnRow = document.createElement('div');
  btnRow.style.cssText = 'display:flex;gap:10px;margin-top:14px;';
  const sendBtn = document.createElement('button');
  sendBtn.textContent = 'Gonder';
  sendBtn.style.cssText = 'flex:1;background:linear-gradient(180deg,#7b5cff,#5a3fd6);color:#fff;border:none;border-radius:14px;padding:10px;font-weight:bold;cursor:pointer;';
  const cancelBtn = document.createElement('button');
  cancelBtn.textContent = 'Bagla';
  cancelBtn.style.cssText = 'flex:1;background:rgba(255,255,255,0.1);color:#fff;border:none;border-radius:14px;padding:10px;font-weight:bold;cursor:pointer;';
  btnRow.appendChild(sendBtn);
  btnRow.appendChild(cancelBtn);
  box.appendChild(title);
  box.appendChild(input);
  box.appendChild(btnRow);
  overlay.appendChild(box);
  document.body.appendChild(overlay);
  input.focus();
  const close = () => document.body.removeChild(overlay);
  cancelBtn.onclick = close;
  overlay.onclick = (e) => { if (e.target === overlay) close(); };
  sendBtn.onclick = () => {
    const val = input.value.trim();
    if (val) { onSend(val); playPingSound(); }
    close();
  };
}
const privateConversations = {};
let activeThreadUserId = null;
function addToConversation(userId, userName, sender, text) {
  if (!privateConversations[userId]) privateConversations[userId] = { name: userName, messages: [] };
  privateConversations[userId].name = userName;
  privateConversations[userId].messages.push({ sender, text });
}
function renderThreadMessages() {
  const list = document.getElementById('thread-message-list');
  if (!list) return;
  const conv = privateConversations[activeThreadUserId];
  list.innerHTML = '';
  (conv ? conv.messages : []).forEach(function(m) {
    const line = document.createElement('div');
    line.style.cssText = 'margin:6px 0;display:flex;' + (m.sender === 'me' ? 'justify-content:flex-end;' : 'justify-content:flex-start;');
    const bubble = document.createElement('div');
    bubble.style.cssText = 'max-width:75%;padding:8px 12px;border-radius:14px;font-size:14px;word-break:break-word;' + (m.sender === 'me' ? 'background:#7b5cff;color:#fff;' : 'background:#2c2c3e;color:#fff;');
    bubble.textContent = m.text;
    line.appendChild(bubble);
    list.appendChild(line);
  });
  list.scrollTop = list.scrollHeight;
}
function openConversationThread(userId, userName) {
  activeThreadUserId = String(userId);
  const existing = document.getElementById('conversation-thread-panel');
  if (existing) existing.parentNode.removeChild(existing);
  const panel = document.createElement('div');
  panel.id = 'conversation-thread-panel';
  panel.style.cssText = 'position:fixed;bottom:20px;right:20px;width:280px;height:380px;max-width:90vw;background:#181820;z-index:99998;display:flex;flex-direction:column;box-shadow:0 6px 30px rgba(0,0,0,0.6);border-radius:18px;overflow:hidden;';
  const header = document.createElement('div');
  header.style.cssText = 'padding:14px;background:#22222e;color:#fff;font-weight:bold;display:flex;justify-content:space-between;align-items:center;';
  const nameSpan = document.createElement('span');
  nameSpan.textContent = userName;
  const closeBtn = document.createElement('span');
  closeBtn.textContent = 'X';
  closeBtn.style.cssText = 'cursor:pointer;color:#ff5555;font-weight:bold;padding:0 6px;';
  closeBtn.onclick = function() {
    activeThreadUserId = null;
    if (panel.parentNode) panel.parentNode.removeChild(panel);
  };
  header.appendChild(nameSpan);
  header.appendChild(closeBtn);
  const list = document.createElement('div');
  list.id = 'thread-message-list';
  list.style.cssText = 'flex:1;overflow-y:auto;padding:10px;';
  const inputRow = document.createElement('div');
  inputRow.style.cssText = 'display:flex;padding:10px;gap:8px;border-top:1px solid rgba(255,255,255,0.1);';
  const input = document.createElement('input');
  input.type = 'text';
  input.placeholder = 'Mesaj yaz...';
  input.style.cssText = 'flex:1;background:#0f0f18;color:#fff;border:1px solid rgba(255,255,255,0.15);border-radius:14px;padding:8px 12px;outline:none;font-size:14px;';
  input.addEventListener('keydown', function(e) { e.stopPropagation(); });
  input.addEventListener('keyup', function(e) { e.stopPropagation(); });
  input.addEventListener('keypress', function(e) { e.stopPropagation(); });
  const sendBtn = document.createElement('button');
  sendBtn.textContent = 'Gonder';
  sendBtn.style.cssText = 'background:linear-gradient(180deg,#7b5cff,#5a3fd6);color:#fff;border:none;border-radius:14px;padding:8px 14px;font-weight:bold;cursor:pointer;';
  sendBtn.onclick = function() {
    const val = input.value.trim();
    if (!val) return;
    addToConversation(userId, userName, 'me', val);
    if (window.__privMsgSession) window.__privMsgSession.viewerPrivateMessage(userId, val);
    input.value = '';
    renderThreadMessages();
    playPingSound();
  };
  input.addEventListener('keydown', function(e) { if (e.key === 'Enter') sendBtn.onclick(); });
  inputRow.appendChild(input);
  inputRow.appendChild(sendBtn);
  panel.appendChild(header);
  panel.appendChild(list);
  panel.appendChild(inputRow);
  panel.appendChild(inputRow);
  document.body.appendChild(panel);
  renderThreadMessages();
}
function showIncomingMessagePopup(senderId, senderName, text) {
  playPingSound();
  addToConversation(senderId, senderName, 'them', text);
  if (activeThreadUserId === String(senderId)) {
    renderThreadMessages();
    return;
  }
  const box = document.createElement('div');
  box.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);background:linear-gradient(180deg,#2c2c3e,#1a1a28);color:#fff;padding:14px 18px;border-radius:16px;z-index:99999;box-shadow:0 6px 20px rgba(0,0,0,0.4);border:1px solid rgba(255,255,255,0.1);max-width:280px;font-size:14px;cursor:pointer;';
  box.innerHTML = '<b>' + senderName + '</b><br>' + text;
  box.onclick = function() {
    if (box.parentNode) box.parentNode.removeChild(box);
    openConversationThread(senderId, senderName);
  };
  document.body.appendChild(box);
  setTimeout(function() { if (box.parentNode) box.parentNode.removeChild(box); }, 8000);
}
function showPrettyAlert(message, title) {
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:100000;display:flex;align-items:center;justify-content:center;';
  const box = document.createElement('div');
  box.style.cssText = 'background:linear-gradient(180deg,#2c2c3e,#1a1a28);border-radius:20px;padding:22px;width:270px;box-shadow:0 10px 40px rgba(0,0,0,0.5);border:1px solid rgba(232,197,107,0.3);text-align:center;color:#fff;';
  if (title) {
    const t = document.createElement('div');
    t.textContent = title;
    t.style.cssText = 'font-weight:bold;font-size:16px;margin-bottom:8px;color:#e8c56b;';
    box.appendChild(t);
  }
  const m = document.createElement('div');
  m.style.cssText = 'white-space:pre-line;font-size:14px;line-height:1.5;margin-bottom:14px;';
  m.textContent = message;
  box.appendChild(m);
  const btn = document.createElement('button');
  btn.textContent = 'Tamam';
  btn.style.cssText = 'width:100%;background:linear-gradient(180deg,#e8c56b,#c9a24f);color:#1a1a28;border:none;border-radius:14px;padding:10px;font-weight:bold;cursor:pointer;';
  btn.onclick = function() { document.body.removeChild(overlay); };
  box.appendChild(btn);
  overlay.appendChild(box);
  document.body.appendChild(overlay);
}
window.applySeasonalTheme = function() {
  if (document.getElementById('seasonal-overlay')) return;
  const month = new Date().getMonth();
  let season;
  if (month === 11 || month === 0 || month === 1) season = 'winter';
  else if (month >= 2 && month <= 4) season = 'spring';
  else if (month >= 5 && month <= 7) season = 'summer';
  else season = 'autumn';
  const particleMap = {
    winter: { emoji: '\u2744', count: 22 },
    spring: { emoji: '\ud83c\udf38', count: 16 },
    summer: { emoji: '\u2b50', count: 8 },
    autumn: { emoji: '\ud83c\udf42', count: 16 }
  };
  const conf = particleMap[season];
  if (!document.getElementById('season-style')) {
    const s = document.createElement('style');
    s.id = 'season-style';
    s.textContent = '@keyframes seasonFall { 0% { transform: translateY(-30px) rotate(0deg); opacity:0; } 10% { opacity:0.85; } 100% { transform: translateY(110vh) rotate(360deg); opacity:0; } }';
    document.head.appendChild(s);
  }
  const overlay = document.createElement('div');
  overlay.id = 'seasonal-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;pointer-events:none;z-index:400;overflow:hidden;';
  for (let i = 0; i < conf.count; i++) {
    const p = document.createElement('div');
    p.textContent = conf.emoji;
    p.style.cssText = 'position:absolute;top:-30px;left:' + (Math.random() * 100) + '%;font-size:' + (14 + Math.random() * 14) + 'px;animation:seasonFall ' + (8 + Math.random() * 8) + 's linear infinite;animation-delay:' + (Math.random() * 10) + 's;';
    overlay.appendChild(p);
  }
  document.body.appendChild(overlay);
};
window.__videoScale2 = 1;
window.toggleVideoSize = function() {
  window.__videoScale2 = window.__videoScale2 >= 1.5 ? 1 : window.__videoScale2 + 0.25;
  const iframes = document.querySelectorAll('iframe[src*="youtube"]');
  iframes.forEach(function(f) {
    const parent = f.parentElement;
    if (parent) {
      if (!parent.dataset.origWidth) {
        parent.dataset.origWidth = parent.offsetWidth;
        parent.dataset.origHeight = parent.offsetHeight;
      }
      const ow = Number(parent.dataset.origWidth);
      const oh = Number(parent.dataset.origHeight);
      parent.style.width = (ow * window.__videoScale2) + 'px';
      parent.style.height = (oh * window.__videoScale2) + 'px';
      parent.style.transition = 'width 0.2s, height 0.2s';
      f.style.width = '100%';
      f.style.height = '100%';
    }
  });
};
if (!document.getElementById('video-resize-btn')) {
  const resizeBtn = document.createElement('div');
  resizeBtn.id = 'video-resize-btn';
  resizeBtn.textContent = '+/-';
  resizeBtn.style.cssText = 'position:fixed;bottom:80px;right:10px;background:rgba(0,0,0,0.6);color:#fff;padding:8px 12px;border-radius:20px;font-size:12px;font-weight:bold;z-index:600;cursor:pointer;';
  resizeBtn.onclick = function() { if (window.toggleVideoSize) window.toggleVideoSize(); };
  document.body.appendChild(resizeBtn);
}
