function getPhotoFrame(pw, ph, iw, ih) {
  const KIMAGE = iw / ih;
  const KPHOTO = pw / ph;
  if (KIMAGE <= KPHOTO) {
    const k = pw / iw;
    return {
      x: 0,
      y: 0,
      width: k * iw,
      height: k * ih
    };
  }
  const k = ph / ih;
  const w = k * iw;
  return {
    x: (pw - w) / 2,
    y: 0,
    width: k * iw,
    height: k * ih
  };
}
