class Group extends DisplayObject {
  constructor(el) {
    super(el || document.createElement('div'));
    this.children = [];
  }
  addChild(child) {
    if (child instanceof DisplayObject) {
      if (child.parent) throw new Error('Already added');
    }
    this.children.push(child);
    this.el.appendChild(child.el);
    if (child instanceof DisplayObject) {
      child.parent = this;
      this.scaleChild(child);
    }
    return child;
  }
  removeChildren() {
    while (this.children.length > 0) this.removeChild(this.children[0]);
  }
  removeChild(child) {
    if (child instanceof DisplayObject) {
      if (child.parent !== this) throw new Error('Not a child');
    }
    const idx = this.children.indexOf(child);
    if (idx < 0) throw new Error('Not in children');
    this.children.splice(idx, 1);
    this.el.removeChild(child.el);
    if (child instanceof DisplayObject) {
      child.parent = undefined;
    }
    return child;
  }
  draw() {
    if (this._state & (I.SCALE | I.SCALE_ESTIMATE)) {
      for (const child of this.children) {
        if (child instanceof DisplayObject) this.scaleChild(child);
      }
    }
    super.draw();
  }
  scaleChild(child) {
    child.parentScaleX = this.parentScaleX * this.scaleX;
    child.parentScaleY = this.parentScaleY * this.scaleY;
  }
}
