function once(fn) {
  let isProcessing = false;
  return function () {
    if (isProcessing) return;
    isProcessing = true;
    const result = fn(...arguments);
    if (result instanceof Promise) {
      result.finally(() => {
        isProcessing = false;
      });
    } else {
      isProcessing = false;
    }
  };
}
